  Definition scK2 (gp tp s11 : word) (F : bvmap 5 word) (fc : bv 32) (s : as_St H) (LB : list block) (LF : list fframe)
      (bs ioc D N allocb regb cfgb schedb lo B shi : Z) (sp ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 : word) (m0 : mem) (mo : Model)
      : config -> Prop :=
    fun c => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 xs7 t3 t4 t5 t6 m (errv : word) (s' : as_St H) (spa ff fp : Z) (gap : list cell)
                    (p0 p8 p16 j16 j32 : list byte) (h3 : word)
                    (p1 : bptr) (v : Z) (p2 : bptr) (q : Z) (p3 : bptr) (stb : Z) (p4 : bptr) (va : Z) (p5 : bptr) (A : Z) (XS : list (Z * Z))
                    (j7 je j4 : list byte) (LB2 : list block),
      as_VIS H s' (cfg_ms c) = MS (mkR (Z_to_bv 64 P_SC_RET_PREP) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (Z_to_bv 64 A) (Z_to_bv 64 N) a2 a3 a4 a5 a6 a7
                                       (Z_to_bv 64 ff) (Z_to_bv 64 bs) (Z_to_bv 64 D) (Z_to_bv 64 N) (Z_to_bv 64 (stb + 32)) xs7
                                       (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
                                  F (ret_pc (Z_to_bv 64 P_SC_RET_PREP)) fc None m (seg_rom asegs)
      /\ (spa = bv_unsigned sp + -128 \/ spa = bv_unsigned sp + -144) /\ fresh_frame H LF 1 ff fp
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv asegs m /\ stk asegs m lo spa
      /\ rw_cells asegs m (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m B /\ as_RHEAP H s LB m0 /\ as_RFS H LF m0
      /\ rw_cells asegs m spa [CB 8 p0; CB 8 p8; CB 8 p16; C8 (Z_to_bv 64 ff)]
      /\ rw_cells asegs m (spa + 32) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 32)
      /\ rw_cells asegs m (bv_unsigned sp + -96) (hz_saved s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
      /\ rw_cells asegs m ff (sc_frm ff ioc fp h3 j16 j32) /\ rw_cells asegs m (Z.shiftr ff 3 + 2147450880) sc_sh0 /\ rw_cells asegs m fp [C1 (b8 1)]
      /\ rw_cells asegs m bs [C8 (wz (stb + 32)); C8 (wz stb); CB 16 (poison_bytes 16 0)] /\ accessible m bs 32
      /\ ro_cells asegs m ioc (IoCtxCells allocb regb schedb)
      /\ as_RHEAP H s' LB2 m /\ (N = 0 -> LB2 = mi_LB p1 v p2 q p3 stb p4 va LB) /\ (1 <= N -> LB2 = (p5, A, N) :: mi_LB p1 v p2 q p3 stb p4 va LB)
      /\ rblock_range v NEWSZ_SSVC /\ rblock_range q SZ_SPCI_IMPL /\ rblock_range stb SZ_SPCI_STATE /\ rblock_range va 8
      /\ (1 <= N -> rblock_range A N /\ addressable m A N /\ exists junk, rw_cells asegs m A [CB (Z.to_nat N) junk]) /\ (N = 0 -> A = 0)
      /\ ARegistry (mi_LB p1 v p2 q p3 stb p4 va LB) m regb ioc v 0
      /\ AStreamSvc (mi_LB p1 v p2 q p3 stb p4 va LB) m v (mkSVC AVP_SSVC 0 AG_ID_SSVC ioc schedb P_A_DESTROY_ALLOC_SSVC) q
      /\ AImplBlock (mi_LB p1 v p2 q p3 stb p4 va LB) m q (impl_after va stb)
      /\ AAllocImpl (mi_LB p1 v p2 q p3 stb p4 va LB) m allocb
      /\ AConfigSvc (mi_LB p1 v p2 q p3 stb p4 va LB) m cfgb (cfg_hdr ioc)
      /\ AScheduler (mi_LB p1 v p2 q p3 stb p4 va LB) m schedb (mkSCH (sched_hdr ioc cfgb) 0 0 0)
      /\ AXStatics2 m
      (* [comment removed for export] *)
      /\ rw_cells asegs m stb (SpcHdrCells (mkSPC AVP_SPCI_STATE 1 1 1) j7)
      /\ rw_cells asegs m (stb + 32) (AnyExecCells (stb + 32) ioc je)
      /\ rw_cells asegs m (stb + 88) [C8 (wz (q + O_SPC_STORAGE)); C8 (wz q)]
      /\ APMutex m (stb + 104) 0
      /\ rw_cells asegs m (stb + 32 + 112) [C8 (wz A); C8 (wz A); C8 (wz A); C8 (wz (A + N)); C8 (wz (A + N)); C8 (wz u64max)]
      /\ APCond m (stb + 192) 0
      /\ rw_cells asegs m (stb + 240) [C8 (wz 0); C4 (wz STREAM_OK); CB 4 j4; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max)]
      /\ addressable m stb SZ_SPCI_STATE
      /\ as_RFS H ((1, ff, fp) :: LF) m /\ ACONST m /\ stack0 m lo shi
      /\ Forall (fs_scratch H LF) XS
      /\ xpres H LB (bv_unsigned sp) ([(bs, bs + SZ_BS); (regb, regb + NEWSZ_REG)]%Z ++ XS) m0 m
      /\ as_AL H s' >= as_AL H s - stream_ctor_cost H N.

  (* [comment removed for export] *)
  Lemma sc_prep_cases : forall (LB1 LB2 : list block) (m : mem) (N : Z) (FB2 : fbv) (fb : Z) (pd : bptr),
      0 <= N -> fb_prepare_rel H LB1 FB_empty N LB2 FB2 -> AFlatBuf LB2 m fb FB2 [] ->
      (forall p b n, In (p, b, n) LB1 -> 0 < b) ->
      exists (p5 : bptr) (A : Z),
        (N = 0 -> LB2 = LB1) /\ (1 <= N -> LB2 = (p5, A, N) :: LB1)
        /\ (1 <= N -> rblock_range A N /\ addressable m A N /\ exists junk, rw_cells asegs m A [CB (Z.to_nat N) junk])
        /\ (N = 0 -> A = 0)
        /\ rw_cells asegs m fb [C8 (wz A); C8 (wz A); C8 (wz A); C8 (wz (A + N)); C8 (wz (A + N)); C8 (wz u64max)]
        /\ fb_out FB2 = A.
  Proof.
    intros LB1 LB2 m N FB2 fb pd NR REL AFB POS.
    destruct (Z.eq_dec N 0) as [N0|NZ].
    - subst N. unfold fb_prepare_rel in REL.
      replace (fb_prep_inplace FB_empty 0 || fb_prep_slide FB_empty 0) with true in REL by reflexivity.
      replace (fb_prep_small FB_empty 0) with FB_empty in REL by reflexivity.
      destruct REL as [EFB ELB]. subst FB2. exists pd, 0.
      destruct AFB as (FBC & _). unfold FlatBufCells in FBC. cbn [fb_begin fb_in fb_out fb_last fb_end FB_empty] in FBC.
      split; [intros _; exact ELB|]. split; [intros K; exfalso; clear - K; lia|]. split; [intros K; exfalso; clear - K; lia|].
      split; [intros _; reflexivity|]. split; [exact FBC| reflexivity].
    - assert (NZ' : 1 <= N) by (clear - NR NZ; lia). clear NZ.
      assert (NS : fb_newsize FB_empty N = N) by (unfold fb_newsize, fb_size, FB_empty; cbn [fb_in fb_out]; clear - NZ'; lia).
      unfold fb_prepare_rel in REL. rewrite NS in REL.
      replace (fb_prep_inplace FB_empty N || fb_prep_slide FB_empty N) with false in REL
        by (unfold fb_prep_inplace, fb_prep_slide, fb_cap, fb_size, FB_empty; cbn [fb_begin fb_in fb_out fb_last fb_end];
            symmetry; apply orb_false_intro; apply Z.leb_gt; clear - NZ'; lia).
      destruct REL as (p5 & A & BRN & EFB & [[_ ELB]|(p0 & IN0 & _)]).
      2:{ exfalso. cbn [fb_begin fb_cap fb_end FB_empty] in IN0. unfold fb_cap in IN0. cbn [fb_begin fb_end FB_empty] in IN0.
          pose proof (POS _ _ _ IN0) as K0. clear - K0. lia. }
      unfold fb_prep_grow in EFB. rewrite NS in EFB. unfold fb_size, FB_empty in EFB. cbn [fb_in fb_out] in EFB.
      rewrite Z.add_0_r in EFB. subst FB2. exists p5, A.
      pose proof (rblock_bounds _ _ BRN) as (W0 & _ & _ & W3 & _). unfold AIMG_TOP in W3.
      destruct AFB as (FBC & _ & _ & FDATA & FADDR).
      assert (NE : mkFB A A A (A + N) (A + N) <> FB_empty) by (intros E; apply (f_equal fb_begin) in E; cbn [fb_begin FB_empty] in E; clear - E W3; lia).
      destruct (FDATA NE) as (pre & junk & FD). pose proof (FADDR NE) as AD. clear FDATA FADDR.
      cbn [fb_begin fb_in fb_out fb_end] in FD. unfold fb_cap in AD. cbn [fb_begin fb_end] in AD.
      replace (A - A) with 0 in FD by (clear; lia). replace (A + N - A) with N in FD, AD by (clear; lia).
      apply (proj1 (rw_cells_app _ _ _ [_; _] [_])) in FD. destruct FD as [_ FD]. cbn [cells_size csize Nat.add length Z.to_nat] in FD.
      rewrite Z.add_0_r in FD.
      unfold FlatBufCells in FBC. cbn [fb_begin fb_in fb_out fb_last fb_end] in FBC.
      split; [intros K; exfalso; clear - K NZ'; lia|]. split; [intros _; exact ELB|].
      split; [intros _; split; [exact BRN| split; [exact AD| exists junk; exact FD]]|].
      split; [intros K; exfalso; clear - K NZ'; lia|]. split; [exact FBC| reflexivity].
  Qed.
